    ed.rig.manager->setTimeDivision(Show::BPM_4_4);
    QVERIFY(ed.openRecordings());
    const QVector<quint32> order{5, id, 1};
    QTRY_COMPARE(ed.rowIds(), order);

    // selection, Ctrl and a Shift range from an anchor, both ways
    ed.click(ed.row(id));
